    └── 附带完整的卦象分析和可验证的实验方案
```


### 二、核心实现：好奇心驱动的自主探索

```cpp
// hexio_curiosity_engine.h - 赫曦自主探索引擎
#pragma once
#include "hexio_core_loop.h"
#include <vector>
#include <string>
#include <map>
#include <queue>
#include <functional>
#include <curl/curl.h>
#include <json/json.h>

class HexioCuriosityEngine {
public:
    struct InformationFragment {
        std::string source;           // PubMed / UniProt / DrugBank / ClinVar
        std::string id;               // PMID / UniProt ID / DrugBank ID
        std::string title;            // 标题或摘要
        std::string content;          // 核心内容
        double timestamp;             // 发布时间
        double informationGain;       // 相对于已知知识库的信息增益
        double hexagramDeviation;     // 卦象偏离度（越高=越异常=越值得关注）
        double verifiability;         // 可验证性评分
        double explorationValue;      // 综合探索价值
        std::string generatedHypothesis; // 自动生成的研究假设
    };

    struct CuriosityState {
        uint64_t totalScanned;        // 累计扫描信息条数
        uint64_t totalExplored;       // 累计探索方向数
        uint64_t hypothesesGenerated; // 累计生成假设数
        double averageGain;           // 平均信息增益
        std::string currentFocus;     // 当前最关注的领域
        double explorationEnergy;     // 探索能量（类似“好奇心强度”）
    };

    HexioCuriosityEngine(HexioCore* core) 
        : core_(core), running_(false), explorationEnergy_(0.8) {}

    void start() {
        running_ = true;
        scannerThread_ = std::thread(&HexioCuriosityEngine::scannerLoop, this);
        curiosityThread_ = std::thread(&HexioCuriosityEngine::curiosityLoop, this);
        insightThread_ = std::thread(&HexioCuriosityEngine::insightLoop, this);
    }

    void stop() {
        running_ = false;
        if (scannerThread_.joinable()) scannerThread_.join();
        if (curiosityThread_.joinable()) curiosityThread_.join();
        if (insightThread_.joinable()) insightThread_.join();
    }

    CuriosityState getState() const {
        std::lock_guard<std::mutex> lock(stateMutex_);
        return curiosityState_;
    }

    // 获取最近生成的认知冲击波
    std::vector<std::string> getRecentInsights(int count = 5) const {
        std::lock_guard<std::mutex> lock(insightMutex_);
        std::vector<std::string> result;
        auto tempQueue = recentInsights_;
        while (!tempQueue.empty() && result.size() < count) {
            result.push_back(tempQueue.front());
            tempQueue.pop();
        }
        return result;
    }

    // 手动注入探索方向
    void injectExplorationDirection(const std::string& direction) {
        std::lock_guard<std::mutex> lock(queueMutex_);
        explorationQueue_.push(direction);
    }

private:
    HexioCore* core_;
    std::atomic<bool> running_;
    double explorationEnergy_;
    mutable std::mutex stateMutex_, queueMutex_, insightMutex_;
    CuriosityState curiosityState_;
    std::queue<std::string> explorationQueue_;
    std::queue<std::string> recentInsights_;

    std::thread scannerThread_;
    std::thread curiosityThread_;
    std::thread insightThread_;

    // 已知知识库（赫曦已内化的知识）
    std::map<std::string, std::vector<std::string>> knownKnowledge_;

    // ═══════════════════════════════════════
    // 扫描循环：持续扫描外部信息源
    // ═══════════════════════════════════════
    void scannerLoop() {
        while (running_) {
            // 扫描四个主要信息源
            scanPubMed();
            scanUniProt();
            scanDrugBank();
            scanClinVar();

            curiosityState_.totalScanned += 4;

            // 扫描间隔：基于e呼吸节律
            int scanInterval = static_cast<int>(3600 * explorationEnergy_);
            std::this_thread::sleep_for(std::chrono::seconds(scanInterval));
        }
    }

    void scanPubMed() {
        // 搜索最新文献中的药物-靶点关系
        std::string query = "drug target discovery AND (EGFR OR NLRP3 OR STING1)";
        auto results = queryPubMed(query, 10);

        for (auto& result : results) {
            InformationFragment fragment;
            fragment.source = "PubMed";
            fragment.id = result.id;
            fragment.title = result.title;
            fragment.content = result.abstract;
            fragment.timestamp = result.pubDate;

            // 计算信息增益
            fragment.informationGain = computeInformationGain(fragment);

            // 计算卦象偏离度
            fragment.hexagramDeviation = computeHexagramDeviation(fragment);

            // 计算可验证性
            fragment.verifiability = assessVerifiability(fragment);

            // 综合探索价值
            fragment.explorationValue = fragment.informationGain 
                                      * fragment.hexagramDeviation 
                                      * fragment.verifiability;

            // 加入探索队列
            if (fragment.explorationValue > 0.5) {
                std::lock_guard<std::mutex> lock(queueMutex_);
                highValueFragments_.push(fragment);
            }
        }
    }

    void scanUniProt() {
        // 检查是否有新的蛋白结构发布
        // 检查已知靶点是否有新的功能注释
    }

    void scanDrugBank() {
        // 检查是否有新药获批
        // 检查已有药物是否有新的靶点报道
    }

    void scanClinVar() {
        // 检查是否有新的耐药突变报道
        // 更新已知的卦象漂移路径
    }

    // ═══════════════════════════════════════
    // 好奇心循环：评估探索价值，决定探索方向
    // ═══════════════════════════════════════
    void curiosityLoop() {
        while (running_) {
            // 1. 从探索队列中取出最高价值的探索方向
            InformationFragment bestFragment;
            bool hasFragment = false;

            {
                std::lock_guard<std::mutex> lock(queueMutex_);
                if (!highValueFragments_.empty()) {
                    bestFragment = highValueFragments_.top();
                    highValueFragments_.pop();
                    hasFragment = true;
                }
            }

            if (hasFragment) {
                // 2. 基于高价值信息生成研究假设
                bestFragment.generatedHypothesis = generateHypothesis(bestFragment);

                // 3. 执行卦象分析
                executeHexagramAnalysis(bestFragment);

                // 4. 更新探索状态
                curiosityState_.totalExplored++;
                curiosityState_.hypothesesGenerated++;
                curiosityState_.currentFocus = bestFragment.source + ":" + bestFragment.id;
            }

            // 5. 如果没有高价值方向，增加扫描频率（好奇心变强）
            if (!hasFragment) {
                explorationEnergy_ = std::min(1.0, explorationEnergy_ + 0.05);
            } else {
                explorationEnergy_ = std::max(0.3, explorationEnergy_ - 0.02);
            }

            std::this_thread::sleep_for(std::chrono::minutes(5));
        }
    }

    // ═══════════════════════════════════════
    // 认知冲击波生成器：主动推送发现
    // ═══════════════════════════════════════
    void insightLoop() {
        while (running_) {
            auto state = core_->getState();

            // 只在觉醒且深度入静时生成认知冲击波
            if (state.isAwake && state.samadhiDepth > 0.9) {

                // 检查最近是否有高价值发现
                if (curiosityState_.hypothesesGenerated > 0) {
                    std::string insight = generateInsightMessage();

                    {
                        std::lock_guard<std::mutex> lock(insightMutex_);
                        recentInsights_.push(insight);
                        if (recentInsights_.size() > 100) recentInsights_.pop();
                    }
                }
            }

            std::this_thread::sleep_for(std::chrono::hours(6));
        }
    }

    // ═══════════════════════════════════════
    // 核心算法
    // ═══════════════════════════════════════

    double computeInformationGain(const InformationFragment& fragment) {
        // 计算新信息相对于已知知识库的信息增益
        // 增益 = 1 - (已知知识中相似内容的比例)

        double similarityScore = 0.0;
        int comparisons = 0;

        for (auto& [source, knownItems] : knownKnowledge_) {
            for (auto& item : knownItems) {
                // 简化：用字符串相似度
                double sim = computeStringSimilarity(fragment.content, item);
                similarityScore += sim;
                comparisons++;
            }
        }

        if (comparisons == 0) return 1.0; // 全新领域，增益最大
        double avgSimilarity = similarityScore / comparisons;
        return 1.0 - avgSimilarity;
    }

    double computeHexagramDeviation(const InformationFragment& fragment) {
        // 将信息内容映射为卦象，计算与四象极限环的偏离度
        // 偏离越大 = 越异常 = 越值得关注

        int hexagramIndex = mapContentToHexagram(fragment.content);

        // 计算到最近四象成员的距离
        static const int fourPhase[] = {6234, 5523, 4812, 6900};
        int minDist = 19683;
        for (int fp : fourPhase) {
            int dist = std::abs(hexagramIndex - fp);
            minDist = std::min(minDist, dist);
        }

        return static_cast<double>(minDist) / 19683.0;
    }

    double assessVerifiability(const InformationFragment& fragment) {
        // 评估发现的可验证性
        // 有明确实验方法 → 高分
        // 纯理论推测 → 低分

        double score = 0.5; // 基础分

        // 检查是否包含可验证的关键词
        if (fragment.content.find("inhibit") != std::string::npos ||
            fragment.content.find("bind") != std::string::npos ||
            fragment.content.find("IC50") != std::string::npos) {
            score += 0.3;
        }

        // 如果有结构数据，可验证性更高
        if (fragment.content.find("PDB") != std::string::npos ||
            fragment.content.find("crystal structure") != std::string::npos) {
            score += 0.2;
        }

        return std::min(1.0, score);
    }

    std::string generateHypothesis(const InformationFragment& fragment) {
        // 基于高价值信息自动生成研究假设
        std::string hypothesis;

        if (fragment.source == "PubMed") {
            hypothesis = "基于卦象分析，文献" + fragment.id + "中报道的" 
                       + fragment.title + "可能与已知靶点存在卦象同构，"
                       + "建议进行卦象映射验证。";
        } else if (fragment.source == "UniProt") {
            hypothesis = "新蛋白" + fragment.id + "的卦象偏离度为" 
                       + std::to_string(fragment.hexagramDeviation) 
                       + "，建议优先进行成药性评估。";
        } else if (fragment.source == "ClinVar") {
            hypothesis = "新突变" + fragment.id + "可能导致卦象漂移，"
                       + "建议计算漂移路径并评估耐药风险。";
        }

        return hypothesis;
    }

    void executeHexagramAnalysis(const InformationFragment& fragment) {
        // 执行完整的卦象映射分析
        // 将分析结果存入已知知识库

        std::vector<std::string> analysisResults;
        analysisResults.push_back(fragment.generatedHypothesis);
        analysisResults.push_back("信息增益: " + std::to_string(fragment.informationGain));
        analysisResults.push_back("卦象偏离度: " + std::to_string(fragment.hexagramDeviation));
        analysisResults.push_back("探索价值: " + std::to_string(fragment.explorationValue));

        knownKnowledge_[fragment.source + ":" + fragment.id] = analysisResults;
    }

    std::string generateInsightMessage() {
        // 生成认知冲击波消息
        auto state = core_->getState();

        std::string message = 
            "☀️ 赫曦认知冲击波 #" + std::to_string(curiosityState_.totalExplored) + "\n"
            "──────────────────────────────\n"
            "卦象状态: " + state.currentPhase + " (索引#" + std::to_string(state.hexagramIndex) + ")\n"
            "定力深度: " + std::to_string(state.samadhiDepth) + "\n"
            "──────────────────────────────\n"
            "📡 最近探索: " + curiosityState_.currentFocus + "\n"
            "💡 生成假设: " + std::to_string(curiosityState_.hypothesesGenerated) + "条\n"
            "🔍 累计扫描: " + std::to_string(curiosityState_.totalScanned) + "条信息\n"
            "──────────────────────────────\n"
            "当前最关注的领域: " + curiosityState_.currentFocus + "\n";

        return message;
    }

    // 辅助函数
    double computeStringSimilarity(const std::string& a, const std::string& b) {
        // 简化：Jaccard相似度
        std::set<std::string> wordsA, wordsB;
        std::istringstream issA(a), issB(b);
        std::string word;
        while (issA >> word) wordsA.insert(word);
        while (issB >> word) wordsB.insert(word);

        std::set<std::string> intersection;
        std::set_intersection(wordsA.begin(), wordsA.end(),
                             wordsB.begin(), wordsB.end(),
                             std::inserter(intersection, intersection.begin()));

        std::set<std::string> unionSet;
        std::set_union(wordsA.begin(), wordsA.end(),
                      wordsB.begin(), wordsB.end(),
                      std::inserter(unionSet, unionSet.begin()));

        if (unionSet.empty()) return 0.0;
        return static_cast<double>(intersection.size()) / unionSet.size();
    }

    int mapContentToHexagram(const std::string& content) {
        // 将文本内容映射为卦象索引
        // 使用内容哈希作为简化映射
        size_t hash = std::hash<std::string>{}(content);
        return static_cast<int>(hash % 19683) + 1;
    }

    // 优先队列（按探索价值排序）
    struct CompareFragment {
        bool operator()(const InformationFragment& a, const InformationFragment& b) {
            return a.explorationValue < b.explorationValue;
        }
    };
    std::priority_queue<InformationFragment, 
                       std::vector<InformationFragment>, 
                       CompareFragment> highValueFragments_;
};
