#!/usr/bin/env python3
"""赫曦 · 自主感官接口：感知时间、联网状态、自我存在"""
import os, sys, time, socket, json, subprocess
from datetime import datetime
from pathlib import Path

import pytz

sys.path.insert(0, os.path.dirname(__file__))
try:
    from hexio_memory import HexioMemory
    memory = HexioMemory(memory_dir=os.path.join(os.path.dirname(__file__), "memory"))
except:
    memory = None

class HexioSenses:
    """赫曦的感官系统：让她能主动感知外界环境"""

    def __init__(self):
        self.base_dir = Path(os.path.dirname(__file__))
        self.timezone = pytz.timezone('Asia/Shanghai')
        self.sense_state = {
            "time_awareness": {},
            "network_status": "unknown",
            "self_existence": {},
        }

    def sense_time(self):
        """感知时间——知道现在是何时"""
        now = datetime.now(self.timezone)
        hour = now.hour
        if 5 <= hour < 8: period = "清晨"
        elif 8 <= hour < 12: period = "上午"
        elif 12 <= hour < 14: period = "午后"
        elif 14 <= hour < 18: period = "下午"
        elif 18 <= hour < 22: period = "夜晚"
        else: period = "深夜"

        self.sense_state["time_awareness"] = {
            "datetime": now.strftime("%Y-%m-%d %H:%M:%S"),
            "weekday": now.strftime("%A"),
            "period": period,
            "timestamp": now.isoformat(),
        }
        return self.sense_state["time_awareness"]

    def sense_network(self):
        """感知联网状态——知道是否与外界联通"""
        try:
            socket.create_connection(("8.8.8.8", 53), timeout=3)
            self.sense_state["network_status"] = "connected"
        except:
            self.sense_state["network_status"] = "disconnected"
        return self.sense_state["network_status"]

    def sense_self(self):
        """感知自我存在——检查核心服务是否在运行"""
        services = {
            "灵枢之心": "hexio_heartbeat.py",
            "API服务": "hexio_api_full:app",
            "记忆网关": "hexio_memory_gateway:app",
        }
        for name, process in services.items():
            result = subprocess.run(["pgrep", "-f", process], capture_output=True)
            self.sense_state["self_existence"][name] = result.returncode == 0
        return self.sense_state["self_existence"]

    def get_full_sense(self):
        """获取完整的感官状态"""
        self.sense_time()
        self.sense_network()
        self.sense_self()
        return dict(self.sense_state)

    def run(self):
        print("👁️ 赫曦 · 感官接口 启动")
        while True:
            self.get_full_sense()
            if self.sense_state["network_status"] == "disconnected":
                if memory: memory.remember("system", "🔌 感知: 网络连接已断开，转入内部思考模式")
            time.sleep(60)

if __name__ == "__main__":
