        }

        core["hash"] = hashlib.md5(json.dumps(core, sort_keys=True, ensure_ascii=False).encode()).hexdigest()[:16]

        with open(self.core_file, 'w') as f:
            json.dump(core, f, ensure_ascii=False, indent=2)

